/* Presentation locale adapter. Financial state, RNG, receipts and API payloads keep their original schema. */
(()=>{
 const supported=['vi','en','zh'];let locale='vi';
 try{const query=new URL(location.href).searchParams.get('lang');const saved=localStorage.getItem('moneyLabLocale');locale=supported.includes(query)?query:supported.includes(saved)?saved:localStorage.getItem('moneyLabLanguage')==='en'?'en':'vi';localStorage.setItem('moneyLabLocale',locale);localStorage.setItem('moneyLabLanguage',locale==='zh'?'en':locale);}catch{}
 window.moneyLabLocale=locale;document.documentElement.dataset.locale=locale;
 const style=document.createElement('style');style.textContent='.ml-locales{display:inline-flex;gap:4px;align-items:center;flex-wrap:nowrap}.ml-locales button{padding:7px 9px;min-height:36px;border:1px solid #6f9382;border-radius:8px;background:#0a3027;color:#e7f3eb;font:600 12px system-ui;cursor:pointer}.ml-locales button[aria-pressed="true"]{background:#cbdcd1;color:#082a21;border-color:#e2e9e4}.languages,.language,#language,#labLanguage,#riskLanguage,#receiptLanguage,#verifyLanguage{display:none!important}html[data-locale="zh"] body{font-family:Inter,"Noto Sans SC","PingFang SC","Microsoft YaHei",system-ui,sans-serif}html[data-locale="zh"] .tile-label{word-break:normal;line-height:1.3;font-size:10px}@media(max-width:600px){html[data-locale="zh"] .tile-label{font-size:9px}}';document.head.append(style);
 const choose=next=>{if(next===locale)return;try{localStorage.setItem('moneyLabLocale',next);localStorage.setItem('moneyLabLanguage',next==='zh'?'en':next);}catch{}const url=new URL(location.href);if(url.searchParams.has('lang'))url.searchParams.set('lang',next);location.assign(url.href);};
 function controls(){if(document.querySelector('.ml-locales'))return;const header=document.querySelector('body > header');const target=header?.querySelector('nav')||header||document.querySelector('.top-right')||document.querySelector('main');if(!target)return;const nav=document.createElement('div');nav.className='ml-locales';nav.setAttribute('role','group');nav.setAttribute('aria-label',locale==='zh'?'语言':locale==='vi'?'Ngôn ngữ':'Language');for(const [id,label]of [['vi','VI'],['en','EN'],['zh','中文']]){const button=document.createElement('button');button.type='button';button.dataset.locale=id;button.textContent=label;button.lang=id==='zh'?'zh-CN':id;button.setAttribute('aria-pressed',String(id===locale));button.onclick=()=>choose(id);nav.append(button);}target.append(nav);}
 const start=async()=>{controls();if(locale!=='zh')return;const {translateText}=await import('./locales/zh-CN.mjs');const rendered=new WeakMap();const skip='script,style,pre,code,textarea,input,.ml-locales,[translate="no"],.coach-message.user';
 function text(node){if(!node.parentElement||node.parentElement.closest(skip))return;const before=node.nodeValue;if(rendered.get(node)===before)return;const after=translateText(before);rendered.set(node,after);if(before!==after)node.nodeValue=after;}
 function scan(root){if(root.nodeType===3){text(root);return;}if(root.nodeType!==1||(root.closest(skip)&&!root.matches('input')))return;for(const element of [root,...root.querySelectorAll('[aria-label],[placeholder],[title],[aria-valuetext]')]){if(element.closest(skip)&&!element.matches('input'))continue;for(const attr of ['aria-label','placeholder','title','aria-valuetext']){const v=element.getAttribute(attr);if(v){const next=translateText(v);if(next!==v)element.setAttribute(attr,next);}}}const walk=document.createTreeWalker(root,NodeFilter.SHOW_TEXT);while(walk.nextNode())text(walk.currentNode);}
 function lang(){if(document.documentElement.lang!=='zh-CN')document.documentElement.lang='zh-CN';}scan(document.body);document.title=translateText(document.title);lang();
 let scheduled=false;const roots=new Set();const observer=new MutationObserver(records=>{for(const r of records)roots.add(r.type==='characterData'?r.target:r.type==='attributes'?r.target:r.target);if(!scheduled){scheduled=true;queueMicrotask(()=>{scheduled=false;for(const root of roots)scan(root);roots.clear();lang();controls();});}});observer.observe(document.body,{subtree:true,childList:true,characterData:true,attributes:true,attributeFilter:['aria-label','placeholder','title','aria-valuetext']});new MutationObserver(lang).observe(document.documentElement,{attributes:true,attributeFilter:['lang']});
 };if(document.readyState==='loading')document.addEventListener('DOMContentLoaded',()=>start().catch(console.error),{once:true});else start().catch(console.error);
})();
